import { showStartupFailure } from "@app/startup-failure";

// The icon stylesheet is generated by the Vite plugin and must be imported as
// its virtual module. Importing "@codenhub/icons" from CSS resolves to the
// package's plain base sheet instead, which has no per-icon mask rules, and
// every icon renders as a solid block.
import "virtual:icons.css";
import "./styles/index.css";

// The interface is loaded behind a dynamic import so that an error while its
// modules load or it starts, which no error boundary can catch, replaces the
// splash with something to act on instead of leaving it up for good.
try {
  await import("./boot");
} catch (error) {
  showStartupFailure(error);
}
